(()=>{const incomeInput=document.getElementById('isrGuideIncome');const periodInput=document.getElementById('isrGuidePeriod');const button=document.getElementById('isrGuideCalculate');const result=document.getElementById('isrGuideResult');const context=document.getElementById('isrGuideContext');const personalExplain=document.getElementById('isrGuidePersonalExplain');const marginalBar=document.getElementById('isrGuideMarginalBar');const effectiveBar=document.getElementById('isrGuideEffectiveBar');const marginalValue=document.getElementById('isrGuideMarginalValue');const effectiveValue=document.getElementById('isrGuideEffectiveValue');const rateNote=document.getElementById('isrGuideRateNote');if(!incomeInput||!periodInput||!button||!result)return;const TABLES={mensual:[[0.01,844.59,0,1.92],[844.60,7168.51,16.22,6.40],[7168.52,12598.02,420.95,10.88],[12598.03,14644.64,1011.68,16.00],[14644.65,17533.64,1339.14,17.92],[17533.65,35362.83,1856.84,21.36],[35362.84,55736.68,5665.16,23.52],[55736.69,106410.50,10457.09,30.00],[106410.51,141880.66,25659.23,32.00],[141880.67,425641.99,37009.69,34.00],[425642.00,Infinity,133488.54,35.00]],quincenal:[[0.01,416.70,0,1.92],[416.71,3537.15,7.95,6.40],[3537.16,6216.15,207.75,10.88],[6216.16,7225.95,499.20,16.00],[7225.96,8651.40,660.75,17.92],[8651.41,17448.75,916.20,21.36],[17448.76,27501.60,2795.25,23.52],[27501.61,52505.25,5159.70,30.00],[52505.26,70006.95,12660.75,32.00],[70006.96,210020.70,18261.30,34.00],[210020.71,Infinity,65866.05,35.00]],semanal:[[0.01,194.46,0,1.92],[194.47,1650.67,3.71,6.40],[1650.68,2900.87,96.95,10.88],[2900.88,3372.11,232.96,16.00],[3372.12,4037.32,308.35,17.92],[4037.33,8142.75,427.56,21.36],[8142.76,12834.08,1304.45,23.52],[12834.09,24502.45,2407.86,30.00],[24502.46,32669.91,5908.35,32.00],[32669.92,98009.66,8521.94,34.00],[98009.67,Infinity,30737.49,35.00]]};const PERIOD_LABELS={mensual: 'mensual',quincenal: 'quincenal (15 días)',semanal: 'semanal (7 días)'};const money=value=>new Intl.NumberFormat('es-MX',{style: 'currency',currency: 'MXN',minimumFractionDigits:2}).format(value);function setBar(el,value){if(!el)return;const pct=Math.max(0,Math.min(100,value/35*100));el.style.width= `${pct}%`;}function calculate(){const income=Number(incomeInput.value);const period=periodInput.value;const table=TABLES[period];if(!Number.isFinite(income)||income<=0){result.innerHTML= '<p><strong>Captura un ingreso mayor que $0 y asegúrate de que corresponda al periodo elegido.</strong></p>';if(context)context.hidden=true;return;}const rowIndex=table.findIndex(r=>income>=r[0]&&income<=r[1]);const row=table[rowIndex];if(!row)return;const[lower,upper,fixed,rate]=row;const excess=Math.max(0,income-lower);const taxOnExcess=excess*rate/100;const estimated=fixed+taxOnExcess;const effective=income>0?estimated/income*100:0;const upperText=Number.isFinite(upper)?money(upper): 'en adelante';const periodLabel=PERIOD_LABELS[period];result.innerHTML= `
      <div class="isr-mini-grid">
        <div><span>Periodo</span><strong>${periodLabel}</strong></div>
        <div><span>Tu rango 2026</span><strong>${money(lower)} – ${upperText}</strong></div>
        <div><span>Tasa marginal</span><strong>${rate.toFixed(2)}%</strong></div>
        <div><span>Límite inferior</span><strong>${money(lower)}</strong></div>
        <div><span>Excedente</span><strong>${money(excess)}</strong></div>
        <div><span>Cuota fija</span><strong>${money(fixed)}</strong></div>
        <div><span>ISR estimado por tarifa</span><strong>${money(estimated)}</strong></div>
        <div><span>Tasa efectiva aprox.</span><strong>${effective.toFixed(2)}%</strong></div>
      </div>
      <div class="isr-mini-explain">
        <strong>Así se forma:</strong>
        <code>${money(income)} − ${money(lower)} = ${money(excess)}</code>
        <code>${money(excess)} × ${rate.toFixed(2)}% = ${money(taxOnExcess)}</code>
        <code>${money(taxOnExcess)} + ${money(fixed)} = ${money(estimated)}</code>
      </div>`;if(context)context.hidden=false;if(marginalValue)marginalValue.textContent= `${rate.toFixed(2)}%`;if(effectiveValue)effectiveValue.textContent= `${effective.toFixed(2)}%`;setBar(marginalBar,rate);setBar(effectiveBar,effective);if(rateNote){rateNote.textContent= `La tasa marginal de ${rate.toFixed(2)}% se aplica al excedente de ${money(excess)}, no a los ${money(income)} completos.`;}if(personalExplain){const ordinal=rowIndex+1;const difference=Math.max(0,rate-effective);personalExplain.innerHTML= `
        <strong>Qué significa tu resultado</strong>
        <p>Con un ingreso ${periodLabel} de <strong>${money(income)}</strong>, caes en el <strong>rango ${ordinal} de 11</strong> de la tarifa utilizada por esta herramienta.</p>
        <p>Solo <strong>${money(excess)}</strong> rebasa el límite inferior de <strong>${money(lower)}</strong>. Por eso una tasa marginal de <strong>${rate.toFixed(2)}%</strong> no equivale a descontar ese porcentaje de todo tu ingreso.</p>
        <p>En este ejemplo, la tasa efectiva aproximada es <strong>${effective.toFixed(2)}%</strong>${difference > 0 ? `,unos<strong>${difference.toFixed(2)}puntos porcentuales</strong>por debajo de la tasa marginal.` : '.'}</p>
      `;}}button.addEventListener('click',calculate);incomeInput.addEventListener('keydown',e=>{if(e.key=== 'Enter')calculate();});periodInput.addEventListener('change',()=>{if(incomeInput.value)calculate();});document.querySelectorAll('[data-isr-guide-preset]').forEach(preset=>{preset.addEventListener('click',()=>{incomeInput.value=preset.dataset.isrGuidePreset;calculate();});});})();
